INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_033_M5_S3', 'culverts', '3', 'culverts: Enclosed conduits that convey water beneath roads, railways, or other embankments. In Hydraulic Structures, the focus is on the analysis, design, implementation, interpretation, or evaluation of culverts within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Structures module establishes its technical context.', 'SSD_COURSE_033_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M5_S4', 'energy dissipators', '4', 'energy dissipators: Hydraulic structures that reduce flow energy and velocity to limit downstream erosion and damage. In Hydraulic Structures, the focus is on the analysis, design, implementation, interpretation, or evaluation of energy dissipators within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Structures module establishes its technical context.', 'SSD_COURSE_033_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M5_S5', 'intake structures', '5', 'intake structures: Structures that control and convey water from a river, reservoir, or other source into a hydraulic system. In Hydraulic Structures, the focus is on the analysis, design, implementation, interpretation, or evaluation of intake structures within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Structures module establishes its technical context.', 'SSD_COURSE_033_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M6_S1', 'surge pressure', '1', 'surge pressure: Pressure change caused by rapid changes in flow velocity in a pressurised conduit. In Transient Flow and Water Hammer, the focus is on the analysis, design, implementation, interpretation, or evaluation of surge pressure within Hydraulics and Hydraulic Engineering, particularly where the Transient Flow and Water Hammer module establishes its technical context.', 'SSD_COURSE_033_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M6_S2', 'elastic pipe flow', '2', 'elastic pipe flow: Transient flow behaviour in which pressure waves and pipe-wall elasticity are important. In Transient Flow and Water Hammer, the focus is on the analysis, design, implementation, interpretation, or evaluation of elastic pipe flow within Hydraulics and Hydraulic Engineering, particularly where the Transient Flow and Water Hammer module establishes its technical context.', 'SSD_COURSE_033_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M6_S3', 'wave speed', '3', 'wave speed: Speed at which a pressure disturbance propagates through a fluid-conduit system. In Transient Flow and Water Hammer, the focus is on the analysis, design, implementation, interpretation, or evaluation of wave speed within Hydraulics and Hydraulic Engineering, particularly where the Transient Flow and Water Hammer module establishes its technical context.', 'SSD_COURSE_033_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M6_S4', 'surge control', '4', 'surge control: Measures used to limit pressure transients in hydraulic systems and protect pipelines, equipment, and structures from excessive surge pressures. In Transient Flow and Water Hammer, the focus is on the analysis, design, implementation, interpretation, or evaluation of surge control within Hydraulics and Hydraulic Engineering, particularly where the Transient Flow and Water Hammer module establishes its technical context.', 'SSD_COURSE_033_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M7_S1', 'network analysis', '1', 'network analysis: Analysis of connected hydraulic pipes, nodes, pumps, and controls to determine flow distribution and pressure or head conditions. In Hydraulic System Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of network analysis within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic System Design module establishes its technical context.', 'SSD_COURSE_033_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M7_S2', 'pump selection', '2', 'pump selection: Choosing a pump and operating point that satisfy required flow, head, efficiency, control, and system constraints. In Hydraulic System Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of pump selection within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic System Design module establishes its technical context.', 'SSD_COURSE_033_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M7_S3', 'system curves', '3', 'system curves: Relationships between required system head and discharge for a hydraulic network. In Hydraulic System Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of system curves within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic System Design module establishes its technical context.', 'SSD_COURSE_033_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M7_S4', 'operational control', '4', 'operational control: Methods for regulating hydraulic systems during operation to maintain required flows, levels, pressures, and safe operating conditions. In Hydraulic System Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of operational control within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic System Design module establishes its technical context.', 'SSD_COURSE_033_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M1_S1', 'mineral identification', '1', 'mineral identification: Identification of minerals using properties such as hardness, cleavage, lustre, colour, streak, and specific gravity. In Minerals and Rocks, the focus is on the analysis, design, implementation, interpretation, or evaluation of mineral identification within Engineering Geology, particularly where the Minerals and Rocks module establishes its technical context.', 'SSD_COURSE_034_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M1_S2', 'igneous rocks', '2', 'igneous rocks: Rocks formed by the cooling and solidification of molten magma or lava. In Minerals and Rocks, the focus is on the analysis, design, implementation, interpretation, or evaluation of igneous rocks within Engineering Geology, particularly where the Minerals and Rocks module establishes its technical context.', 'SSD_COURSE_034_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M1_S3', 'sedimentary rocks', '3', 'sedimentary rocks: Rocks formed from deposited sediments or from chemical or biological processes at or near the Earth''s surface. In Minerals and Rocks, the focus is on the analysis, design, implementation, interpretation, or evaluation of sedimentary rocks within Engineering Geology, particularly where the Minerals and Rocks module establishes its technical context.', 'SSD_COURSE_034_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M1_S4', 'metamorphic rocks', '4', 'metamorphic rocks: Rocks formed when existing rocks are altered by heat, pressure, and chemically active fluids without complete melting. In Minerals and Rocks, the focus is on the analysis, design, implementation, interpretation, or evaluation of metamorphic rocks within Engineering Geology, particularly where the Minerals and Rocks module establishes its technical context.', 'SSD_COURSE_034_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M2_S1', 'physical weathering', '1', 'physical weathering: Breakdown of rock into smaller pieces without changing its mineral composition. In Weathering and Geological Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of physical weathering within Engineering Geology, particularly where the Weathering and Geological Processes module establishes its technical context.', 'SSD_COURSE_034_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M2_S2', 'chemical weathering', '2', 'chemical weathering: Alteration or decomposition of minerals through chemical reactions with water, gases, or dissolved substances. In Weathering and Geological Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of chemical weathering within Engineering Geology, particularly where the Weathering and Geological Processes module establishes its technical context.', 'SSD_COURSE_034_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M2_S3', 'erosion', '3', 'erosion: Removal and transport of weathered soil or rock by water, wind, ice, or gravity. In Weathering and Geological Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of erosion within Engineering Geology, particularly where the Weathering and Geological Processes module establishes its technical context.', 'SSD_COURSE_034_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M2_S4', 'mass wasting', '4', 'mass wasting: Downslope movement of soil or rock primarily under the influence of gravity. In Weathering and Geological Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of mass wasting within Engineering Geology, particularly where the Weathering and Geological Processes module establishes its technical context.', 'SSD_COURSE_034_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M3_S1', 'bedding', '1', 'bedding: Layering in sedimentary rocks produced by changes in depositional conditions. In Geological Structures and Discontinuities, the focus is on the analysis, design, implementation, interpretation, or evaluation of bedding within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'SSD_COURSE_034_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M3_S2', 'folds', '2', 'folds: Bends or curved structures formed when rock layers are deformed. In Geological Structures and Discontinuities, the focus is on the analysis, design, implementation, interpretation, or evaluation of folds within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'SSD_COURSE_034_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M3_S3', 'faults', '3', 'faults: Fractures or zones of displacement in rock along which relative movement has occurred. In Geological Structures and Discontinuities, the focus is on the analysis, design, implementation, interpretation, or evaluation of faults within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'SSD_COURSE_034_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M3_S4', 'joints', '4', 'joints: Planar fractures in rock along which little or no displacement has occurred. In Geological Structures and Discontinuities, the focus is on the analysis, design, implementation, interpretation, or evaluation of joints within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'SSD_COURSE_034_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M3_S5', 'shear zones', '5', 'shear zones: Zones of concentrated rock deformation characterised by significant shear displacement or strain. In Geological Structures and Discontinuities, the focus is on the analysis, design, implementation, interpretation, or evaluation of shear zones within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'SSD_COURSE_034_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M4_S1', 'geological mapping', '1', 'geological mapping: Systematic recording of rock units, structures, landforms, and geological features at a site or region. In Engineering Site Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of geological mapping within Engineering Geology, particularly where the Engineering Site Characterization module establishes its technical context.', 'SSD_COURSE_034_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M4_S2', 'discontinuity surveys', '2', 'discontinuity surveys: Field measurement of joints, bedding, faults, and other rock discontinuities for engineering assessment. In Engineering Site Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of discontinuity surveys within Engineering Geology, particularly where the Engineering Site Characterization module establishes its technical context.', 'SSD_COURSE_034_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M4_S3', 'rock mass description', '3', 'rock mass description: Systematic characterization of intact rock and discontinuities, including weathering, jointing, strength, spacing, and condition. In Engineering Site Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of rock mass description within Engineering Geology, particularly where the Engineering Site Characterization module establishes its technical context.', 'SSD_COURSE_034_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M4_S4', 'geophysical methods', '4', 'geophysical methods: Non-invasive methods that infer subsurface conditions from physical properties such as seismic velocity or electrical resistivity. In Engineering Site Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of geophysical methods within Engineering Geology, particularly where the Engineering Site Characterization module establishes its technical context.', 'SSD_COURSE_034_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M5_S1', 'landslides', '1', 'landslides: Rapid or slow downslope movements of soil, rock, or debris along a failure surface. In Geological Hazards, the focus is on the analysis, design, implementation, interpretation, or evaluation of landslides within Engineering Geology, particularly where the Geological Hazards module establishes its technical context.', 'SSD_COURSE_034_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M5_S2', 'earthquakes', '2', 'earthquakes: Sudden release of stored geological strain that generates seismic waves and ground motion. In Geological Hazards, the focus is on the analysis, design, implementation, interpretation, or evaluation of earthquakes within Engineering Geology, particularly where the Geological Hazards module establishes its technical context.', 'SSD_COURSE_034_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M5_S3', 'subsidence', '3', 'subsidence: Downward movement of the ground surface caused by natural or human-induced processes. In Geological Hazards, the focus is on the analysis, design, implementation, interpretation, or evaluation of subsidence within Engineering Geology, particularly where the Geological Hazards module establishes its technical context.', 'SSD_COURSE_034_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M5_S4', 'expansive materials', '4', 'expansive materials: Soils or rocks that undergo significant volume change, particularly swelling and shrinkage, when their moisture state changes. In Geological Hazards, the focus is on the analysis, design, implementation, interpretation, or evaluation of expansive materials within Engineering Geology, particularly where the Geological Hazards module establishes its technical context.', 'SSD_COURSE_034_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M5_S5', 'erosion hazards', '5', 'erosion hazards: Risks to engineering works caused by removal of soil or rock by flowing water, wind, or other agents. In Geological Hazards, the focus is on the analysis, design, implementation, interpretation, or evaluation of erosion hazards within Engineering Geology, particularly where the Geological Hazards module establishes its technical context.', 'SSD_COURSE_034_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M6_S1', 'rock foundations', '1', 'rock foundations: Foundations bearing on or socketed into rock, designed using rock-mass strength, discontinuities, deformation, and groundwater conditions. In Geology for Foundations and Excavations, the focus is on the analysis, design, implementation, interpretation, or evaluation of rock foundations within Engineering Geology, particularly where the Geology for Foundations and Excavations module establishes its technical context.', 'SSD_COURSE_034_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M6_S2', 'slope stability inputs', '2', 'slope stability inputs: Geological, geometric, groundwater, and material parameters required for slope-stability analysis. In Geology for Foundations and Excavations, the focus is on the analysis, design, implementation, interpretation, or evaluation of slope stability inputs within Engineering Geology, particularly where the Geology for Foundations and Excavations module establishes its technical context.', 'SSD_COURSE_034_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M6_S3', 'tunnelling geology', '3', 'tunnelling geology: Geological conditions that influence tunnel alignment, excavation method, support, groundwater, and stability. In Geology for Foundations and Excavations, the focus is on the analysis, design, implementation, interpretation, or evaluation of tunnelling geology within Engineering Geology, particularly where the Geology for Foundations and Excavations module establishes its technical context.', 'SSD_COURSE_034_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M6_S4', 'excavation conditions', '4', 'excavation conditions: Ground and groundwater conditions that affect excavation stability, support, dewatering, and construction methods. In Geology for Foundations and Excavations, the focus is on the analysis, design, implementation, interpretation, or evaluation of excavation conditions within Engineering Geology, particularly where the Geology for Foundations and Excavations module establishes its technical context.', 'SSD_COURSE_034_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M7_S1', 'dams', '1', 'dams: Water-retaining structures whose design depends on foundation geology, materials, seepage, and geological hazards. In Geology in Infrastructure Projects, the focus is on the analysis, design, implementation, interpretation, or evaluation of dams within Engineering Geology, particularly where the Geology in Infrastructure Projects module establishes its technical context.', 'SSD_COURSE_034_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M7_S2', 'tunnels', '2', 'tunnels: Underground structures whose construction and performance depend strongly on rock mass and groundwater conditions. In Geology in Infrastructure Projects, the focus is on the analysis, design, implementation, interpretation, or evaluation of tunnels within Engineering Geology, particularly where the Geology in Infrastructure Projects module establishes its technical context.', 'SSD_COURSE_034_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M7_S3', 'roads', '3', 'roads: Transport infrastructure whose alignment, cuts, fills, drainage, and foundations must account for geological conditions and hazards. In Geology in Infrastructure Projects, the focus is on the analysis, design, implementation, interpretation, or evaluation of roads within Engineering Geology, particularly where the Geology in Infrastructure Projects module establishes its technical context.', 'SSD_COURSE_034_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M7_S4', 'groundwater', '4', 'groundwater: Water occupying the saturated zone beneath the ground surface and stored or transmitted through soil and rock formations. In Geology in Infrastructure Projects, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_034_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_034_M7_S5', 'geological risk assessment', '5', 'geological risk assessment: Evaluation of geological hazards, their likelihood and consequences, and the measures required to reduce associated project risk. In Geology in Infrastructure Projects, the focus is on the analysis, design, implementation, interpretation, or evaluation of geological risk assessment within Engineering Geology, particularly where the Geology in Infrastructure Projects module establishes its technical context.', 'SSD_COURSE_034_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M1_S1', 'wireframe', '1', 'wireframe refers to a geometric model representing an object using points, curves, and edges without explicit surfaces or solid volume. In Geometric Modelling, the focus is on the analysis, design, implementation, interpretation, or evaluation of wireframe within CAD/CAM, particularly where the Geometric Modelling module establishes its technical context.', 'SSD_COURSE_035_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M1_S2', 'surface modelling', '2', 'surface modelling: Representation of continuous or irregular surfaces in CAD using mathematical surface entities such as patches, splines, or NURBS. In Geometric Modelling, the focus is on the analysis, design, implementation, interpretation, or evaluation of surface modelling within CAD/CAM, particularly where the Geometric Modelling module establishes its technical context.', 'SSD_COURSE_035_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M1_S3', 'solid modelling', '3', 'solid modelling: Computer representation of a three-dimensional object as a complete volume with defined boundaries, enabling geometric operations and engineering analysis. In Geometric Modelling, the focus is on the analysis, design, implementation, interpretation, or evaluation of solid modelling within CAD/CAM, particularly where the Geometric Modelling module establishes its technical context.', 'SSD_COURSE_035_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M1_S4', 'parametric features', '4', 'parametric features: CAD features whose geometry is controlled by dimensions, constraints, and relationships that can be edited systematically. In Geometric Modelling, the focus is on the analysis, design, implementation, interpretation, or evaluation of parametric features within CAD/CAM, particularly where the Geometric Modelling module establishes its technical context.', 'SSD_COURSE_035_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M1_S5', 'constraints', '5', 'constraints: Geometric or dimensional rules that control relationships among sketch or model elements. In Geometric Modelling, the focus is on the analysis, design, implementation, interpretation, or evaluation of constraints within CAD/CAM, particularly where the Geometric Modelling module establishes its technical context.', 'SSD_COURSE_035_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M2_S1', 'sketching', '1', 'sketching: Creating constrained two-dimensional geometry that forms the basis of many parametric CAD features. In Computer-Aided Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of sketching within CAD/CAM, particularly where the Computer-Aided Design module establishes its technical context.', 'SSD_COURSE_035_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M2_S2', 'assemblies', '2', 'assemblies: CAD representations of multiple components positioned and constrained to represent a complete product or mechanism. In Computer-Aided Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of assemblies within CAD/CAM, particularly where the Computer-Aided Design module establishes its technical context.', 'SSD_COURSE_035_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M2_S3', 'design intent', '3', 'design intent refers to the functional and geometric requirements that a CAD model is expected to preserve when dimensions, features, or relationships are changed. In Computer-Aided Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of design intent within CAD/CAM, particularly where the Computer-Aided Design module establishes its technical context.', 'SSD_COURSE_035_M2_S3', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;